    32	/** Every message the inn sent, so the front desk can check what each guest received. */
    33	public final class SentMessages {
    34	
    35	    private final DataSource dataSource;
    36	
    37	    public SentMessages(DataSource dataSource) {
    38	        this.dataSource = dataSource;
    39	    }
    40	
    41	    Message add(String channel, String to, String subject, String body) {
    42	        try (Connection connection = dataSource.getConnection();
    43	                PreparedStatement insert = connection.prepareStatement(
    44	                        "INSERT INTO messages (channel, recipient, subject, body) VALUES (?, ?, ?, ?) RETURNING id")) {
    45	            insert.setString(1, channel);
    46	            insert.setString(2, to);
    47	            insert.setString(3, subject);
    48	            insert.setString(4, body);
    49	            try (ResultSet generated = insert.executeQuery()) {
    50	                generated.next();
    51	                return new Message(generated.getLong("id"), channel, to, subject, body);
    52	            }
    53	        } catch (SQLException failure) {
    54	            throw new IllegalStateException("could not keep the message to " + to, failure);
    55	        }
    56	    }
    57	
    58	    public List<Message> all() {
    59	        try (Connection connection = dataSource.getConnection();
    60	                PreparedStatement select = connection.prepareStatement(
    61	                        "SELECT id, channel, recipient, subject, body FROM messages ORDER BY id");
    62	                ResultSet rows = select.executeQuery()) {
    63	            List<Message> messages = new ArrayList<>();
    64	            while (rows.next()) {
    65	                messages.add(new Message(
    66	                        rows.getLong("id"),
    67	                        rows.getString("channel"),
    68	                        rows.getString("recipient"),
    69	                        rows.getString("subject"),
    70	                        rows.getString("body")));
    71	            }
    72	            return messages;
    73	        } catch (SQLException failure) {
    74	            throw new IllegalStateException("could not read the sent messages", failure);
    75	        }
    76	    }
    77	}
